  "author": {
    "name": "Clint Shryock"
  },
  "homepage": "https://github.com/catsby/claude-code-buddy",
  "repository": "https://github.com/catsby/claude-code-buddy",
  "license": "MIT",
  "keywords": [
    "buddy",
    "pet",
    "ascii",
    "function-hooks",
    "mod"
